// Root middleware: routes page URLs to the library-page / site-page handlers.
//
// Why here and not in _redirects: Cloudflare applies _redirects rules only to
// static asset responses (Pages docs), so a 200 rewrite to
// /.netlify/functions/* resolves the target as a static file and 404s —
// verified in wrangler pages dev. The function-rewrite rules are therefore
// dropped from the Cloudflare _redirects (see
// scripts/lib/cloudflare-redirects.mjs) and the routing lives here.
//
// Static assets never reach this middleware: dist/_routes.json (generated by
// the build when CF_PAGES=1) excludes /assets/*, /_ncn-shells/* and all
// non-HTML file extensions, so only page-ish requests invoke the worker.
// Anything this middleware does not recognise falls through to static
// serving (context.next()), where the remaining _redirects 301s apply.

import pages from '../netlify/lib/ncn-shell/pages.json';
import seed from '../netlify/lib/ncn-library/seed.json';
import {handleFunctionRequest} from './_cf/handlers.mjs';
import {buildLegacyRoutes, resolvePageRoute} from './_cf/page-routes.mjs';

const legacy = buildLegacyRoutes(seed);

export async function onRequest(context) {
  const {request} = context;
  if (request.method !== 'GET' && request.method !== 'HEAD') return context.next();
  const url = new URL(request.url);
  const route = resolvePageRoute(url.pathname, pages, legacy);
  if (!route) return context.next();
  // Reuse the function dispatcher with a synthetic internal request; the
  // handlers check the /.netlify/functions/ prefix to allow internal calls.
  const internal = new Request(url.origin + '/.netlify/functions/' + route.name + route.search, request);
  return handleFunctionRequest({...context, request: internal}, [route.name]);
}
